/**
 * Tests for the #3727 stray-playground-pages SessionStart hook.
 *
 * Real filesystem and a real git repo per case (no fs mocks: a mocked
 * `git status` would certify whatever shape the test fed it, the #3801
 * class). The first case is the control that FAILS on main, where the hook
 * does not exist: a planted, backdated, untracked page under docs/playgrounds
 * must be named in the SessionStart context.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, utimesSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import type { HookInput } from '../../types.js';
import { strayPlaygroundPages, __internals } from '../../lifecycle/stray-playground-pages.js';
import { createTestContext } from '../fixtures/test-context.js';

const { SCOPE_RE } = __internals;
const SID = 'sid-3727-aaaa';
const TWO_HOURS = 2 * 60 * 60 * 1000;

let project: string;

function git(...args: string[]): string {
  return execFileSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@x', ...args], {
    cwd: project, encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'],
  });
}

function plant(rel: string, msAgo = TWO_HOURS): string {
  const full = join(project, rel);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, '<!doctype html><title>x</title>\n');
  const t = (Date.now() - msAgo) / 1000;
  utimesSync(full, t, t);
  return full;
}

function input(overrides: Partial<HookInput> = {}): HookInput {
  return { tool_name: '', session_id: SID, project_dir: project, tool_input: {}, ...overrides } as HookInput;
}

function contextOf(r: ReturnType<typeof strayPlaygroundPages>): string {
  const hso = (r as { hookSpecificOutput?: { additionalContext?: string } }).hookSpecificOutput;
  return hso?.additionalContext ?? '';
}

describe('stray-playground-pages (#3727)', () => {
  const savedEnv: Record<string, string | undefined> = {};
  beforeEach(() => {
    project = mkdtempSync(join(tmpdir(), 'stray-pg-'));
    git('init', '--quiet');
    writeFileSync(join(project, 'README.md'), 'x\n');
    git('add', 'README.md');
    git('commit', '--quiet', '-m', 'init');
    for (const k of ['ORK_NO_STRAY_PLAYGROUND_CHECK', 'ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS']) {
      savedEnv[k] = process.env[k];
      delete process.env[k];
    }
  });
  afterEach(() => {
    rmSync(project, { recursive: true, force: true });
    for (const [k, v] of Object.entries(savedEnv)) {
      if (v === undefined) delete process.env[k]; else process.env[k] = v;
    }
  });

  it('names an untracked page under docs/playgrounds older than the threshold', () => {
    plant('docs/playgrounds/dev/forgotten-explainer.html');
    const r = strayPlaygroundPages(input(), createTestContext({ projectDir: project }));
    expect(r.continue).toBe(true);
    const ctx = contextOf(r);
    expect(ctx).toContain('docs/playgrounds/dev/forgotten-explainer.html');
    expect(ctx).toMatch(/untracked, \dh\)/);
    expect(ctx).toContain('lab-manifest.json');
  });

  it('names an untracked page under a branch-slug dir docs/<type>--<slug>/', () => {
    plant('docs/feat--3727-thing/index.html');
    const ctx = contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })));
    expect(ctx).toContain('docs/feat--3727-thing/index.html');
  });

  it('stays silent when the page is younger than the threshold', () => {
    plant('docs/playgrounds/dev/fresh.html', 5 * 60 * 1000);
    const r = strayPlaygroundPages(input(), createTestContext({ projectDir: project }));
    expect(contextOf(r)).toBe('');
  });

  it('stays silent for a tracked page', () => {
    plant('docs/playgrounds/dev/tracked.html');
    git('add', 'docs/playgrounds/dev/tracked.html');
    git('commit', '--quiet', '-m', 'page');
    expect(contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })))).toBe('');
  });

  it('stays silent for an ignored page', () => {
    writeFileSync(join(project, '.gitignore'), 'docs/playgrounds/tmp/\n');
    plant('docs/playgrounds/tmp/scratch.html');
    expect(contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })))).toBe('');
  });

  it('stays silent for an old untracked file outside the two roots (precision control)', () => {
    plant('docs/other/old.html');
    plant('src/notes.html');
    expect(contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })))).toBe('');
    expect(SCOPE_RE.test('docs/site/a--b.html')).toBe(false);
    expect(SCOPE_RE.test('docs/feat--x/index.html')).toBe(true);
  });

  it('fires once per session id and again for a different session id', () => {
    plant('docs/playgrounds/dev/forgotten.html');
    const ctx = createTestContext({ projectDir: project });
    const first = contextOf(strayPlaygroundPages(input(), ctx));
    const second = contextOf(strayPlaygroundPages(input(), ctx));
    const other = contextOf(strayPlaygroundPages(input({ session_id: 'sid-3727-bbbb' }), ctx));
    expect(first).toContain('forgotten.html');
    expect(second).toBe('');
    expect(other).toContain('forgotten.html');
    expect(existsSync(join(project, '.claude', 'state', `stray-playgrounds-${SID}.json`))).toBe(true);
  });

  it('honours ORK_NO_STRAY_PLAYGROUND_CHECK=1', () => {
    plant('docs/playgrounds/dev/forgotten.html');
    process.env.ORK_NO_STRAY_PLAYGROUND_CHECK = '1';
    expect(contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })))).toBe('');
  });

  it('honours ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS', () => {
    plant('docs/playgrounds/dev/forgotten.html', 30 * 60 * 1000);
    process.env.ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS = '0.25';
    expect(contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })))).toContain('forgotten.html');
    process.env.ORK_STRAY_PLAYGROUND_MIN_AGE_HOURS = 'nonsense';
    expect(__internals.minAgeMs()).toBe(__internals.DEFAULT_MIN_AGE_HOURS * 3600000);
  });

  it('lists at most ten pages and counts the rest', () => {
    for (let i = 0; i < 12; i++) plant(`docs/playgrounds/dev/p${i}.html`);
    const ctx = contextOf(strayPlaygroundPages(input(), createTestContext({ projectDir: project })));
    expect(ctx).toContain('12 untracked playground pages');
    expect(ctx).toContain('...and 2 more');
  });

  it('stays silent and does not throw outside a git repo', () => {
    const bare = mkdtempSync(join(tmpdir(), 'stray-nogit-'));
    try {
      mkdirSync(join(bare, 'docs', 'playgrounds', 'dev'), { recursive: true });
      writeFileSync(join(bare, 'docs', 'playgrounds', 'dev', 'x.html'), 'x');
      const r = strayPlaygroundPages(input({ project_dir: bare }), createTestContext({ projectDir: bare }));
      expect(r.continue).toBe(true);
      expect(contextOf(r)).toBe('');
    } finally {
      rmSync(bare, { recursive: true, force: true });
    }
  });
});
